function solve(n, edges, source) {
  const d = Array(n).fill(Infinity)
  d[source] = 0
  for (const [u, v, w] of edges) {
    if (d[u] + w < d[v]) d[v] = d[u] + w
  }
  return d.map((x) => (x === Infinity ? 'INF' : x))
}
